import { describe, expect, it } from 'vitest';
import { isPlatformVersionAtLeast } from '../../serverless/utils.js';
describe('isPlatformVersionAtLeast', () => {
    it('returns true for 2027.03', () => {
        expect(isPlatformVersionAtLeast('2027.03', 2027, 3)).toBe(true);
    });
    it('returns true for 2027.03-beta', () => {
        expect(isPlatformVersionAtLeast('2027.03-beta', 2027, 3)).toBe(true);
    });
    it('returns true for a later month in the same year', () => {
        expect(isPlatformVersionAtLeast('2027.10', 2027, 3)).toBe(true);
    });
    it('returns true for a later year', () => {
        expect(isPlatformVersionAtLeast('2028.01', 2027, 3)).toBe(true);
    });
    it('returns false for 2026.09', () => {
        expect(isPlatformVersionAtLeast('2026.09', 2027, 3)).toBe(false);
    });
    it('returns false for 2025.2', () => {
        expect(isPlatformVersionAtLeast('2025.2', 2027, 3)).toBe(false);
    });
    it('returns false for a non-version string', () => {
        expect(isPlatformVersionAtLeast('unstable', 2027, 3)).toBe(false);
    });
});
